<template>
  <div class="average-time-chart">
    <apexchart
      :key="isDark ? 'dark' : 'light'"
      type="donut"
      :options="chartOptions"
      :series="chartSeries"
      height="200"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import { mapState } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { amount_format_setting } from 'src/constants';
import dateUtils from 'src/utils/date';
import { formatServiceLabel, formatAmount } from './analyticsUtils';

export default defineComponent({
  name: 'AverageTimeChart',
  components: {
    apexchart: VueApexCharts,
  },
  mixins: [dateUtils],
  props: {
    flowData: {
      type: Array as PropType<Array<{ service: string; avg: number }>>,
      required: true,
    },
    totalAverage: {
      type: Number,
      default: null,
    },
    groupBy: {
      type: String as PropType<'flow' | 'sub_org' | 'doc_type' | 'supplier' | 'assigned_group'>,
      default: 'flow',
    },
    systemAverage: {
      type: Number,
      default: null,
    },
  },
  data() {
    return {
      primaryColor: '#1976D2',
    };
  },
  computed: {
    ...mapState(useSettingStore, ['user_settings']),

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    textColor(): string {
      return this.isDark ? '#ffffff' : '#373d3f';
    },

    // Color for total average based on comparison with system average
    // Green if below system avg, Orange if equal, Red if above
    comparisonColor(): string {
      if (this.systemAverage === null || this.systemAverage === undefined) {
        return this.textColor;
      }
      const currentTotal = this.totalAverage ?? this.flowData.reduce((sum, item) => sum + item.avg, 0);
      // Allow 5% tolerance for "matching" the average
      const tolerance = this.systemAverage * 0.05;
      if (currentTotal < this.systemAverage - tolerance) {
        return '#4CAF50'; // Green - better than average
      } else if (currentTotal > this.systemAverage + tolerance) {
        return '#F44336'; // Red - worse than average
      }
      return '#FF9800'; // Orange - matches average
    },

    chartSeries(): number[] {
      return this.flowData.map(item => {
        const avg = typeof item.avg === 'number' && !Number.isNaN(item.avg) ? item.avg : 0;
        // Use enough precision so sub-second values don't round to 0
        return avg > 0 ? Math.max(parseFloat(avg.toFixed(4)), 0.0001) : 0;
      });
    },

    chartColors(): string[] {
      return this.generateColorPalette(this.primaryColor, Math.max(this.flowData.length, 10));
    },

    chartOptions(): any {
      return {
        chart: {
          type: 'donut',
        },
        labels: this.flowData.map(item => this.formatLabel(item.service)),
        colors: this.chartColors,
        legend: {
          show: false,
        },
        dataLabels: {
          enabled: false,
        },
        plotOptions: {
          pie: {
            donut: {
              size: '65%',
              labels: {
                show: true,
                name: {
                  show: true,
                  fontSize: '12px',
                  fontFamily: 'Roboto, sans-serif',
                  fontWeight: 600,
                  color: this.textColor,
                  offsetY: -10,
                },
                value: {
                  show: true,
                  fontSize: '16px',
                  fontFamily: 'Roboto, sans-serif',
                  fontWeight: 400,
                  color: this.comparisonColor,
                  offsetY: 5,
                  formatter: (val: any) => {
                    return this.formatDuration(parseFloat(val));
                  },
                },
                total: {
                  show: true,
                  showAlways: true,
                  label: this.$t('total_average'),
                  fontSize: '12px',
                  fontFamily: 'Roboto, sans-serif',
                  fontWeight: 600,
                  color: this.comparisonColor,
                  formatter: () => {
                    if (this.totalAverage !== undefined && this.totalAverage !== null) {
                      return this.formatDuration(this.totalAverage);
                    }
                    // Fallback to sum of services if totalAverage not provided
                    const total = this.flowData.reduce((sum, item) => sum + item.avg, 0);
                    return this.formatDuration(total);
                  },
                },
              },
            },
          },
        },
        tooltip: {
          y: {
            formatter: (val: number) => {
              return this.formatDuration(val);
            },
          },
        },
      };
    },
  },
  mounted() {
    const computedStyle = getComputedStyle(document.documentElement);
    const cssColor = computedStyle.getPropertyValue('--primary-color').trim();
    if (/^#[0-9a-fA-F]{6}$/.test(cssColor)) {
      this.primaryColor = cssColor;
    }
  },
  methods: {
    formatAmount(value: number): string {
      const userLocale = this.user_settings.AMOUNTS_LOCALE;
      return formatAmount(value, userLocale);
    },

    formatServiceLabel(service: string): string {
      return formatServiceLabel(service, this.$t);
    },

    formatLabel(label: string): string {
      // Only apply service formatting when grouping by flow
      // For other groupings (supplier, sub_org, doc_type), display the label as-is
      if (this.groupBy === 'flow') {
        return this.formatServiceLabel(label);
      }
      return label;
    },

    hexToHsl(hex: string): { h: number; s: number; l: number } {
      hex = hex.replace(/^#/, '');
      const r = parseInt(hex.substring(0, 2), 16) / 255;
      const g = parseInt(hex.substring(2, 4), 16) / 255;
      const b = parseInt(hex.substring(4, 6), 16) / 255;

      const max = Math.max(r, g, b);
      const min = Math.min(r, g, b);
      let h = 0, s = 0;
      const l = (max + min) / 2;

      if (max !== min) {
        const d = max - min;
        s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
        switch (max) {
          case r: h = ((g - b) / d + (g < b ? 6 : 0)) / 6; break;
          case g: h = ((b - r) / d + 2) / 6; break;
          case b: h = ((r - g) / d + 4) / 6; break;
        }
      }
      return { h: h * 360, s: s * 100, l: l * 100 };
    },

    hslToHex(h: number, s: number, l: number): string {
      s /= 100;
      l /= 100;
      const a = s * Math.min(l, 1 - l);
      const f = (n: number) => {
        const k = (n + h / 30) % 12;
        const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
        return Math.round(255 * color).toString(16).padStart(2, '0');
      };
      return `#${f(0)}${f(8)}${f(4)}`;
    },

    generateColorPalette(baseColor: string, count: number): string[] {
      const { h, s } = this.hexToHsl(baseColor);
      const colors: string[] = [];
      for (let i = 0; i < count; i++) {
        const lightness = 30 + (i * 50 / count); // Range from 30% to 80% lightness
        colors.push(this.hslToHex(h, s, lightness));
      }
      return colors;
    },
  },
});
</script>

<style scoped>
.average-time-chart {
  width: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}
</style>