    chartGroupByOptions(): Array<{ label: string; value: 'flow' | 'sub_org' | 'doc_type' | 'supplier' | 'assigned_group' }> {
      const options: Array<{ label: string; value: 'flow' | 'sub_org' | 'doc_type' | 'supplier' | 'assigned_group' }> = [
        { label: this.$t('flow'), value: 'flow' },
        { label: this.$t('sub_org'), value: 'sub_org' },
        { label: this.$t('document_type'), value: 'doc_type' },
        { label: this.$t('supplier'), value: 'supplier' },
