    topDocumentsLimitOptions(): Array<{ label: string; value: number }> {
      return [
        { label: '5', value: 5 },
        { label: '10', value: 10 },
        { label: '25', value: 25 },
        { label: '50', value: 50 },
        { label: this.$t('all'), value: 0 }
      ];
    },

    filterSupplierList(): Array<{ label: string; value: string }> {
      const stats = this._allStats;
      if (stats.length === 0) {
        return [{ label: this.$t('all'), value: ALL_FILTER_VALUE }];
