      const supplierOptions: Array<{ label: string; value: string }> = [];

      for (const item of stats) {
        const supplierId = item.supplier_id;
        if (supplierId && !seen.has(supplierId)) {
          seen.add(supplierId);
          const name = supplierMap.get(supplierId) || supplierId;
          supplierOptions.push({ label: name, value: supplierId });
        }
