      ];
    },

    // Visible table columns (excluding hidden ones)
    visibleTableColumns(): any[] {
      return this.tableColumns.filter(col => !this.hiddenColumnNames.includes(col.name));
    },

    // Hidden table columns
    hiddenTableColumns(): any[] {
      return this.tableColumns.filter(col => this.hiddenColumnNames.includes(col.name));
    },

    // Canonical column order (includes all columns, for restoring hidden columns to original position)
    tableColumnOrder(): string[] {
      return this.tableColumns.map(col => col.name);
    },

    // Performance: Pre-compute label lookup maps for tableElements
    _subOrgLabelMap(): Map<string, string> {
      const map = new Map<string, string>();
      for (const opt of this.filterSubOrgsList) {
        map.set(opt.value, opt.label);
      }
      return map;
    },

    _docTypeLabelMap(): Map<string, string> {
      const map = new Map<string, string>();
      for (const opt of this.filterDocTypeList) {
        map.set(opt.value, opt.label);
      }
      return map;
    },

    // Table elements - dynamically grouped based on visible columns
    // When columns are hidden, rows are aggregated and min/max/avg are recalculated
    tableElements(): any[] {
      // Performance: Use pre-computed stats filtered by flow type and services
      const filteredStats = this._statsFilteredByFlowAndServices;
      if (filteredStats.length === 0) return [];

      // Performance: Use pre-computed label maps for O(1) lookup
      const subOrgLabelMap = this._subOrgLabelMap;
      const docTypeLabelMap = this._docTypeLabelMap;

      // Determine which columns are visible (not hidden)
      const visibleColNames = new Set(this.visibleTableColumns.map(col => col.name));

      // Build dynamic group key based on visible columns only
      const groupKey = (item: any) => {
        const parts: string[] = [];

        // Only include dimension in key if its column is visible
        if (visibleColNames.has('subOrg')) {
          parts.push(item.sub_org_id || '');
        }
        if (visibleColNames.has('docType')) {
          parts.push(item.doc_type || '');
        }
        if (visibleColNames.has('supplier')) {
          parts.push(item.supplier_id || '');
        }
        if (visibleColNames.has('flowStep')) {
          const normalized = normalizeServiceName(item.service);
          const occurrence = item.status_occurrence || 1;
          parts.push(normalized.startsWith('STATUS_') && occurrence >= 2 ? `${normalized}::${occurrence}` : normalized);
        }
        if (visibleColNames.has('assignedGroup')) {
          parts.push(item.assigned_group_id || '');
        }
        if (visibleColNames.has('documentName')) {
          parts.push(item.document_id || '');
        }
        if (visibleColNames.has('date')) {
          parts.push(item.date || '');
        }

        return parts.join('|');
      };

      // Group data based on dynamic key, collecting time_spent values
      const docGroupMap = new Map<string, {
        sub_org_id: string;
        doc_type: string;
        supplier_id: string;
        assigned_group_id: string;
        service: string;
        status_occurrence: number;
        document_id: string;
        filename: string;
        date: string;
        values: number[];
      }>();

      filteredStats.forEach((item: any) => {
        const key = groupKey(item);
        if (!docGroupMap.has(key)) {
          docGroupMap.set(key, {
            sub_org_id: item.sub_org_id || '',
            doc_type: item.doc_type || '',
            supplier_id: item.supplier_id || '',
            assigned_group_id: item.assigned_group_id || '',
            service: normalizeServiceName(item.service),
            status_occurrence: item.status_occurrence || 1,
            document_id: item.document_id || '',
            filename: item.filename || item.document_id || '',
            date: item.date || '',
            values: [],
          });
        }
        const entry = docGroupMap.get(key)!;
        const timeSpent = item.time_spent || 0;
        if (timeSpent > 0) {
          entry.values.push(timeSpent);
        }
      });

      // Convert to array and create table rows
      const result: any[] = [];
      let index = 0;
      docGroupMap.forEach((entry) => {
        const normalizedName = entry.service;
        const compositeKey = entry.status_occurrence >= 2 ? `${normalizedName}::${entry.status_occurrence}` : normalizedName;
        const capitalizedLabel = this.formatServiceLabel(compositeKey);

        // Performance: Use pre-computed label maps for O(1) lookup instead of .find()
        const subOrgLabel = subOrgLabelMap.get(entry.sub_org_id) || entry.sub_org_id || '-';
        const docTypeLabel = docTypeLabelMap.get(entry.doc_type) || entry.doc_type || '-';

        // Document name: use filename or document_id
        const documentName = entry.filename || '-';

        // Performance: Calculate min/avg/max in single pass (avoids spread operator overhead)
        let minVal = 0;
        let avgVal = 0;
        let maxVal = 0;
        const values = entry.values;
        const len = values.length;
        if (len > 0) {
          let sum = values[0];
          minVal = values[0];
          maxVal = values[0];
          for (let i = 1; i < len; i++) {
            const v = values[i];
            sum += v;
            if (v < minVal) minVal = v;
            if (v > maxVal) maxVal = v;
          }
          avgVal = sum / len;
        }

        result.push({
          id: `${index}`,
          name: normalizedName,
          subOrg: subOrgLabel,
          docType: docTypeLabel,
          supplier: (this.supplierNameMap as Map<string, string>).get(entry.supplier_id) || entry.supplier_id || '-',
          assignedGroup: entry.assigned_group_id ? ((this.groupsMap as Map<string, any>).get(entry.assigned_group_id)?.name || entry.assigned_group_id) : '-',
          documentName: documentName,
          docId: entry.document_id || '-',
          date: entry.date ? this.formatDateAccordingToPreference(entry.date, true) : '-',
          rawDate: entry.date || '', // Performance: Store raw date for sorting
          flowStep: capitalizedLabel,
          avgTime: this.formatDuration(avgVal),
          minTime: this.formatDuration(minVal),
          maxTime: this.formatDuration(maxVal),
          // Performance: Store raw numeric values to avoid re-parsing during sorting
          _avgTimeRaw: avgVal,
          _minTimeRaw: minVal,
          _maxTimeRaw: maxVal,
        });
        index++;
      });

      return result;
    },

    // Sorted table elements - applies user-selected column sorting and pagination
    // Performance: Uses raw numeric values stored in tableElements to avoid re-parsing
    sortedTableElements(): any[] {
      const elements = [...this.tableElements];
      const sortBy = this.tablePagination.sortBy;
      const descending = this.tablePagination.descending;
      const sortMultiplier = descending ? -1 : 1;

      // Performance: Map time columns to their raw counterparts
      const rawTimeColumns: Record<string, string> = {
        'minTime': '_minTimeRaw',
        'avgTime': '_avgTimeRaw',
        'maxTime': '_maxTimeRaw',
      };

      // Apply sorting
      if (!sortBy) {
        // Default sort - use localeCompare for strings
        elements.sort((a, b) => {
          if (a.subOrg !== b.subOrg) return a.subOrg.localeCompare(b.subOrg);
          if (a.docType !== b.docType) return a.docType.localeCompare(b.docType);
          if (a.supplier !== b.supplier) return a.supplier.localeCompare(b.supplier);
          if (a.documentName !== b.documentName) return a.documentName.localeCompare(b.documentName);
          if (a.rawDate !== b.rawDate) return a.rawDate.localeCompare(b.rawDate);
          return a.flowStep.localeCompare(b.flowStep);
        });
      } else {
        // Sort by selected column
        const rawColumn = rawTimeColumns[sortBy];

        if (rawColumn) {
          // Performance: Use pre-computed raw numeric values for time columns
          elements.sort((a, b) => sortMultiplier * (a[rawColumn] - b[rawColumn]));
        } else if (sortBy === 'date') {
          // Sort by raw date string for proper chronological ordering
          elements.sort((a, b) => sortMultiplier * a.rawDate.localeCompare(b.rawDate));
        } else {
          // String columns
          elements.sort((a, b) => {
            const aVal = a[sortBy] || '';
            const bVal = b[sortBy] || '';
            return sortMultiplier * aVal.localeCompare(bVal);
          });
        }
      }

      // Apply pagination - slice to current page
      const page = this.tablePagination.page || 1;
      const rowsPerPage = this.tablePagination.rowsPerPage || 20;
      const startIndex = (page - 1) * rowsPerPage;
      const endIndex = startIndex + rowsPerPage;

      return elements.slice(startIndex, endIndex);
    },

    // Elements (DocumentFlowCards) - computed to react to all filters including document search
    // Hybrid computation: Uses pre-aggregated backend data for large datasets (>= 500 docs)
    elements(): any[] {
      // Early return if no data loaded
      if (!this.flow_data) {
        return [];
      }

      // Local computation from raw data
      // Performance: baseFilteredServiceStats already uses _statsForCurrentFlowType (pre-indexed by flow type)
      const filteredStats = this.baseFilteredServiceStats;
      if (filteredStats.length === 0) return [];

      // Group by service (and status_occurrence for status entries), then by document_id to calculate per-document totals
      // For status entries with occurrence >= 2, use composite key to create separate cards
      const serviceMap = new Map<string, Map<string, number>>();
      const serviceOccurrenceMap = new Map<string, number>(); // Track occurrence per composite key

      filteredStats.forEach((item: any) => {
        const service = item.service;
        const occurrence = item.status_occurrence || 1;
        const normalizedService = normalizeServiceName(service);
        const isStatus = normalizedService.startsWith('STATUS_');

        // For status entries, group by service + occurrence to create separate cards
        const groupKey = isStatus && occurrence > 1 ? `${service}::${occurrence}` : service;

        if (isStatus && occurrence > 1) {
          serviceOccurrenceMap.set(groupKey, occurrence);
        }

        const documentId = item.document_id || 'unknown';
        if (!serviceMap.has(groupKey)) {
          serviceMap.set(groupKey, new Map<string, number>());
        }
        const docMap = serviceMap.get(groupKey)!;
        const currentSum = docMap.get(documentId) || 0;
        docMap.set(documentId, currentSum + (item.time_spent || 0));
      });

      // Performance: Convert map to array with single-pass min/avg/max calculation
      const aggregatedStats: any[] = [];
      serviceMap.forEach((docMap, groupKey) => {
        // Extract base service name from composite key (service::occurrence)
        const baseService = groupKey.includes('::') ? groupKey.split('::')[0] : groupKey;
        const occurrence = serviceOccurrenceMap.get(groupKey) || 1;

        let sum = 0;
        let min = Infinity;
        let max = 0;
        let count = 0;

        docMap.forEach((value) => {
          if (value > 0) {
            sum += value;
            if (value < min) min = value;
            if (value > max) max = value;
            count++;
          }
        });

        if (count > 0) {
          aggregatedStats.push({ service: baseService, occurrence, avg: sum / count, min, max });
        } else {
          aggregatedStats.push({ service: baseService, occurrence, avg: 0, min: 0, max: 0 });
        }
      });

      aggregatedStats.sort((a, b) => compareFlowCards(a, b, getCardOrder));

      const result = aggregatedStats.map((item: any, index: number) => {
        const normalizedName = normalizeServiceName(item.service);
        // Use composite name for uniqueness when occurrence > 1
        const uniqueName = item.occurrence >= 2 ? `${normalizedName}::${item.occurrence}` : normalizedName;
        // formatServiceLabel handles composite keys and occurrence prefix (e.g., "Status: 2. Ready For Validation")
        const displayLabel = this.formatServiceLabel(uniqueName);
        // Get system average for this service
        const systemAvgValue = this.systemAverageByService.get(normalizedName);
        return {
          id: index.toString(),
          name: uniqueName,
          label: displayLabel,
          avgTime: this.formatDuration(item.avg),
          minTime: this.formatDuration(item.min),
          maxTime: this.formatDuration(item.max),
          systemAvg: systemAvgValue !== undefined ? this.formatDuration(systemAvgValue) : null,
          showIcon: index < aggregatedStats.length - 1,
          // Raw values for child components to avoid re-parsing formatted strings
          _avgTimeRaw: item.avg,
          _systemAvgRaw: systemAvgValue !== undefined ? systemAvgValue : null,
        };
      });

      return result;
    },
  },
  watch: {
    topDocsCurrentPage(newValue) {
      this.topDocsPageInput = newValue;
    },
    selectedFlowType(newValue, oldValue) {
      if (newValue !== oldValue) {
        // Skip rebuild if filter state was restored from a saved tab.
        // Dropdown is now independent of card selection, so restored
        // selectedSteps stays as the user left it — no sync needed.
        if (this._skipFlowTypeWatcher) {
          this._skipFlowTypeWatcher = false;
          return;
        }
        // Performance: Defer selection update to avoid double recalculation
        // Use requestAnimationFrame to batch with the DOM update
        requestAnimationFrame(() => {
          // Get service names for the NEW flow type directly from _statsForCurrentFlowType
          // Since selectedFlowType already changed, _statsForCurrentFlowType returns correct data
          const stats = this._statsForCurrentFlowType;
          const serviceNames = new Set<string>();
          for (const item of stats) {
            if (item.service) {
              const normalized = normalizeServiceName(item.service);
              const occurrence = item.status_occurrence || 1;
              // For status entries with occurrence >= 2, use composite key
              if (normalized.startsWith('STATUS_') && occurrence >= 2) {
                serviceNames.add(`${normalized}::${occurrence}`);
              } else {
                serviceNames.add(normalized);
              }
            }
          }
          // Single atomic update - avoids intermediate empty state
          this.selectedServices = serviceNames;
          // Reset dropdown visibility to "show everything" on a fresh tab.
          this.selectedSteps = [ALL_FILTER_VALUE];
          this.prevSelectedSteps = [ALL_FILTER_VALUE];
        });
      }
    },
    // Update pagination rowsNumber when table elements change
    tableElements: {
      handler(newElements: any[]) {
        this.tablePagination.rowsNumber = newElements.length;
      },
      immediate: true,
    },
  },
  mounted() {
    if (!this.user_settings?.[analytics_dashboard_setting] || !this.is_admin) return;
    const dashboard_store = useDashboardStore();
    dashboard_store.quickFilterMap.set('filter', {
      value: 'last_90_days',
      label: 'last_90_days',
    });

    // Load sub-organizations, supplier name map, and groups
    const dropdown_store = useDropdownStore();
    dropdown_store.getSubOrgsList();
    dropdown_store.getSupplierNameMap();
    dropdown_store.prepareGroupsDropdown();

    // Load data from API on initial mount with default date range (today - 90 days)
    this.prepareAnalyticsData(this.currentOrg, this.start_date, this.end_date);

    // Set up ResizeObserver to dynamically calculate cards per row
    this.$nextTick(() => {
      this.setupResizeObserver();
    });
  },
  beforeUnmount() {
    // Clean up ResizeObserver
    if (this.resizeObserver) {
      this.resizeObserver.disconnect();
      this.resizeObserver = null;
    }
    // Clean up window resize listener
    window.removeEventListener('resize', this.handleWindowResize);
    // Performance: Clean up debounce timers
    if (this._filterDebounceTimer) {
      clearTimeout(this._filterDebounceTimer);
      this._filterDebounceTimer = null;
    }
    if (this._documentVisibilityDebounceTimer) {
      clearTimeout(this._documentVisibilityDebounceTimer);
      this._documentVisibilityDebounceTimer = null;
    }
    if (this._serviceSelectionDebounceTimer) {
      clearTimeout(this._serviceSelectionDebounceTimer);
      this._serviceSelectionDebounceTimer = null;
    }
    // Release large cached data and module-level caches to free memory
    clearCaches();
    this.flow_data = null;
    this.system_avg_data = null;
    this._cachedAllStats = null;
    this._cachedStatsFilteredByServices = null;
    this._cachedStatsFilteredByServicesIncludingHidden = null;
    this._cachedSubOrgLabelMapForGrouping = null;
    this._cachedDocTypeLabelMapForGrouping = null;
    this._pendingServiceSelection = null;
  },
  methods: {
    setupResizeObserver(): void {
      const container = this.$refs.flowContainer as HTMLElement;
      if (!container) return;

      // Observe the parent card element instead of flowContainer
      // because flowContainer has overflow-x: auto and doesn't shrink when window shrinks
      const parentCard = container.closest('.q-card') as HTMLElement;
      const observeTarget = parentCard || container;

      // Use ResizeObserver for element size changes
      this.resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          // Account for card padding (16px on each side from q-pa-md) when observing parent card
          const padding = parentCard ? 32 : 0;
          this.calculateCardsPerRow(entry.contentRect.width - padding);
        }
      });

      this.resizeObserver.observe(observeTarget);

      // Also listen to window resize for when the container width changes due to window resize
      window.addEventListener('resize', this.handleWindowResize);

      // Initial calculation - use parent card width if available
      const initialWidth = parentCard ? parentCard.clientWidth - 32 : container.clientWidth;
      this.calculateCardsPerRow(initialWidth);
    },

    handleWindowResize(): void {
      // Use the parent card element for width calculation since
      // flowContainer has overflow-x: auto and doesn't shrink when window shrinks
      const container = this.$refs.flowContainer as HTMLElement;
      const parentCard = container?.closest('.q-card') as HTMLElement;
      if (parentCard) {
        // Account for card padding (16px on each side from q-pa-md)
        const availableWidth = parentCard.clientWidth - 32;
        this.calculateCardsPerRow(availableWidth);
      } else if (container) {
        this.calculateCardsPerRow(container.clientWidth);
      }
    },

    calculateCardsPerRow(containerWidth: number): void {
      // Card width is 220px (from CSS grid-template-columns)
      const cardWidth = 250;
      const minCards = 2;
      const maxCards = 10;

      const calculatedCards = Math.floor(containerWidth / cardWidth);
      this.cardsPerRow = Math.max(minCards, Math.min(maxCards, calculatedCards));
    },

    handleTableSort(payload: { column: string; direction: 'asc' | 'desc' }): void {
      this.tablePagination = {
        ...this.tablePagination,
        sortBy: payload.column,
        descending: payload.direction === 'desc',
      };
    },

    handleTablePaginationUpdate(payload: { page?: number; rowsPerPage?: number }): void {
      this.tablePagination = {
        ...this.tablePagination,
        ...payload,
      };
    },

    filterStatsByFlowType(stats: any[], flowType?: string): any[] {
      const type = flowType || this.selectedFlowType;
      if (type === 'modules') {
        return stats.filter((item: any) => {
          const serviceName = normalizeServiceName(item.service);
          const isUserStatus = serviceName.startsWith('USER_');
          const isStatusPrefixed = serviceName.startsWith('STATUS_');
          return !isUserStatus && !isStatusPrefixed;
        });
      } else if (type === 'user') {
        return stats.filter((item: any) => {
          return normalizeServiceName(item.service).startsWith('USER_');
        });
      } else if (type === 'status') {
        return stats.filter((item: any) => {
          return normalizeServiceName(item.service).startsWith('STATUS_');
        });
      }
      return stats;
    },

    // Determine which flow_type a service belongs to for system average calculation
    getServiceFlowType(serviceName: string): 'processing' | 'status' | 'user' {
      const normalized = normalizeServiceName(serviceName);
      if (normalized.startsWith('STATUS_')) return 'status';
      if (normalized.startsWith('USER_')) return 'user';
      return 'processing';
    },

    formatAmount(value: number): string {
      const userLocale = this.user_settings.AMOUNTS_LOCALE;

      return formatAmount(value, userLocale);
    },

    formatServiceLabel(service: string): string {
      return formatServiceLabel(service, this.$t);
    },

    getGroupByLabel(groupBy: string): string {
      const option = this.chartGroupByOptions.find((opt: { label: string; value: string }) => opt.value === groupBy);
      return option?.label || groupBy;
    },

    async updateSelectedTime(value: { start_date: string; end_date: string }) {
      if (!this.user_settings?.[analytics_dashboard_setting] || !this.is_admin) return;
      this.start_date = value.start_date;
      this.end_date = value.end_date;
      const orgId = getOrgId();
      await this.prepareAnalyticsData(orgId, value.start_date, value.end_date);
    },

    async prepareAnalyticsData(orgId: string, start_date: string, end_date: string) {
      this.processing = true;

      let apiData;
      let systemAvgData;
      try {
        // Get available document types for the organization (for system average)
        const docTypesForAvg = (this.active_doc_type_list || [])
          .filter((item: any) => item.value !== null && item.value !== ALL_FILTER_VALUE && item.label?.toLowerCase() !== 'all')
          .map((item: any) => item.value);

        // Fetch both org data and system average in parallel
        // All filtering (sub_org, doc_type, supplier, search) is done in frontend
        [apiData, systemAvgData] = await Promise.all([
          documentFlowDataService.getData_org({ orgId, start_date, end_date }),
          documentFlowDataService.getSystemAverage(start_date, end_date, docTypesForAvg).catch(() => null)
        ]);
      } catch (error) {
        notify.error(this.$t('ERROR_GETTING_DATA'));
        console.error(error);
        return;
      } finally {
        this.processing = false;
      }

      // Store the API response in flow_data so computed properties react
      // (elements is now a computed property that will automatically update)
      this.flow_data = apiData;
      this._flowDataVersion++; // Invalidate _allStats cache
      this.system_avg_data = systemAvgData;

      // Select all services by default when data loads
      this.$nextTick(() => {
        this.toggleSelectAll(true);
      });
    },

    toggleServiceSelection(card: any) {
      const serviceName = card.name;

      // Performance: Use pending set to batch rapid selection changes
      // Initialize pending set from current selection if not already pending
      if (!this._pendingServiceSelection) {
        this._pendingServiceSelection = new Set(this.selectedServices);
      }

      // Apply toggle to pending set
      if (this._pendingServiceSelection.has(serviceName)) {
        this._pendingServiceSelection.delete(serviceName);
      } else {
        this._pendingServiceSelection.add(serviceName);
      }

      // Performance: Trigger immediate UI update by creating new Set reference
      // This makes _elementSelectionStates recompute immediately for responsive UI
      this._pendingServiceSelection = new Set(this._pendingServiceSelection);

      // Debounce the actual state update to batch rapid clicks
      if (this._serviceSelectionDebounceTimer) {
        clearTimeout(this._serviceSelectionDebounceTimer);
      }

      this._serviceSelectionDebounceTimer = setTimeout(() => {
        // Apply pending changes
        if (this._pendingServiceSelection) {
          this.selectedServices = this._pendingServiceSelection;
          this._pendingServiceSelection = null;
        }
        this._serviceSelectionDebounceTimer = null;
      }, 100); // 100ms debounce for batching rapid clicks
    },

    isServiceSelected(card: any): boolean {
      // Performance: Use pre-computed selection states map
      return this._elementSelectionStates.get(card.name) ?? false;
    },

    toggleSelectAll(value: boolean) {
      // Get currently visible service names from elements
      const visibleServiceNames = new Set(this.elements.map((el: any) => el.name));

      // Cancel any pending individual selection changes
      if (this._serviceSelectionDebounceTimer) {
        clearTimeout(this._serviceSelectionDebounceTimer);
        this._serviceSelectionDebounceTimer = null;
      }
      this._pendingServiceSelection = null;

      if (!value) {
        // Deselect all visible services (keep non-visible ones selected)
        const newSet = new Set(this.selectedServices);
        visibleServiceNames.forEach(name => newSet.delete(name));
        this.selectedServices = newSet;
        return;
      }

      // Select all visible services
      const newSet = new Set(this.selectedServices);
      visibleServiceNames.forEach(name => newSet.add(name));
      this.selectedServices = newSet;
    },

    handleTableSelectionChange(payload: { selectedIds: string[]; selectedRows: any[] }) {
      // Convert selected row IDs back to service names
      const newSet = new Set<string>();
      payload.selectedRows.forEach((row: any) => {
        newSet.add(row.name);
      });
      this.selectedServices = newSet;
    },

    // Search input change handler - IMMEDIATE (frontend filtering with debounce)
    onSearchInputChange(value: string | null) {
      this.documentSearch = value ?? '';
    },

    // Handle Enter key press on search input (no-op now, filtering is immediate)
    onSearchEnterKey() {
      // No-op - filtering is immediate
    },

    // Legacy handler for backward compatibility
    onDocumentSearchChange(value: string) {
      this.onSearchInputChange(value);
    },

    async copyDocumentId(documentId: string) {
      try {
        await navigator.clipboard.writeText(documentId);
        notify.success(this.$t('copied_successfully'));
      } catch {
        notify.error(this.$t('error'));
      }
    },

    // Seeds the dashboard's quickFilterMap with a raw_query predicate for
    // this single document, then navigates. dashboard.vue rebuilds its
    // queryParams from the column-filter store on mount, so the doc
    // appears pre-filtered without any URL-parameter plumbing.
    openDocumentInDashboard(documentId: string) {
      if (!documentId) return;
      const dashboard_store = useDashboardStore();
      const escaped = String(documentId).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
      // Start from an empty map so leftover date-range / status filters
      // can't hide the requested document on the destination dashboard.
      const next = new Map<string, any>();
      next.set('raw_query', `id="${escaped}"`);
      dashboard_store.overWriteFilters(next);
      this.$router.push('/dashboard');
    },

    // Toggle document visibility (exclude/include from calculations) - IMMEDIATE
    toggleDocumentVisibility(documentId: string) {
      if (this.hiddenDocumentIds.has(documentId)) {
        this.hiddenDocumentIds.delete(documentId);
      } else {
        this.hiddenDocumentIds.add(documentId);
      }
      // Debounce the reactivity trigger to batch rapid changes
      if (this._documentVisibilityDebounceTimer) {
        clearTimeout(this._documentVisibilityDebounceTimer);
      }
      this._documentVisibilityDebounceTimer = setTimeout(() => {
        this.hiddenDocumentIds = new Set(this.hiddenDocumentIds);
        this._documentVisibilityDebounceTimer = null;
      }, 150);
    },

    toggleAllDocumentsVisibility() {
      if (this.hiddenDocumentIds.size > 0) {
        // Include all - clear hidden set
        this.hiddenDocumentIds = new Set();
      } else {
        // Exclude all - hide all currently visible documents
        const allDocIds = this.allTopDocumentsIncludingHidden.map((doc: any) => doc.document_id);
        this.hiddenDocumentIds = new Set(allDocIds);
      }
    },

    closeAllDropdowns() {
      const dropdownRefs = ['topDocsSelect', 'avgTimeSelect', 'timeTrendSelect'];
      dropdownRefs.forEach(refName => {
        const selectRef = this.$refs[refName] as any;
        if (selectRef?.hidePopup) {
          selectRef.hidePopup();
        }
      });
    },

    getIconSrc(name: string): string {
      return resolveDocFlowIcon(name);
    },

    onTableIconError(event: Event) {
      const target = event.target as HTMLImageElement;
      target.src = '/images/docflow/field_extraction.svg';
    },

    /**
     * Generic handler for multi-select filter changes.
     * Handles "All" option toggling logic consistently across Sub Org, Doc Type, and Supplier filters.
     *
     * @param newValue - The new array of selected values
     * @param allValue - The sentinel value representing "All" (e.g., currentOrgId or ALL_FILTER_VALUE)
     * @param prevValueKey - Key to access the previous value array on this component
     * @param currentValueKey - Key to set the current value array on this component
     */
    handleMultiSelectChange(
      newValue: string[],
      allValue: string,
      prevValueKey: 'prevSelectedSubOrg' | 'prevSelectedDocType' | 'prevSelectedSupplier' | 'prevSelectedSteps',
      currentValueKey: 'selectedSubOrg' | 'selectedDocType' | 'selectedSupplier' | 'selectedSteps'
    ): void {
      const hasAll = newValue.includes(allValue);
      const hasOthers = newValue.some(v => v !== allValue);

      // If nothing selected, default to "All"
      if (newValue.length === 0) {
        this[currentValueKey] = [allValue];
        this[prevValueKey] = [allValue];
        return;
      }

      // If both "All" and other options are selected, decide based on what was just clicked
      if (hasAll && hasOthers) {
        // Use previous value to determine what was clicked
        const prevValue = this[prevValueKey];
        const hadAllBefore = prevValue.includes(allValue) && prevValue.length === 1;
        if (hadAllBefore) {
          // User clicked a specific option while "All" was selected -> remove "All"
          const result = newValue.filter(v => v !== allValue);
          this[currentValueKey] = result;
          this[prevValueKey] = [...result];
        } else {
          // User clicked "All" while other options were selected -> keep only "All"
          this[currentValueKey] = [allValue];
          this[prevValueKey] = [allValue];
        }
        return;
      }

      this[currentValueKey] = newValue;
      this[prevValueKey] = [...newValue];
    },

    // === APPLY BUTTON PATTERN: Pending filter state management ===

    // Resolve "All" toggle logic for multi-select filters
    // Returns the resolved value array after handling All/specific toggle logic
    resolveMultiSelectValue(newValue: string[], allValue: string, prevValue: string[]): string[] {
      if (newValue.length === 0) return [allValue];

      const hasAll = newValue.includes(allValue);
      const hasOthers = newValue.some(v => v !== allValue);

      if (hasAll && hasOthers) {
        const hadAllBefore = prevValue.includes(allValue) && prevValue.length === 1;
        return hadAllBefore ? newValue.filter(v => v !== allValue) : [allValue];
      }
      return newValue;
    },

    // Handle Sub Org multi-select change - IMMEDIATE (frontend filtering)
    handleSubOrgChange(newValue: string[]) {
      const currentOrgId = getOrgId();
      const resolved = this.resolveMultiSelectValue(newValue, currentOrgId, this.prevSelectedSubOrg);
      this.selectedSubOrg = resolved;
      this.prevSelectedSubOrg = [...resolved];
    },

    // Handle Doc Type multi-select change - IMMEDIATE (frontend filtering)
    handleDocTypeChange(newValue: string[]) {
      const resolved = this.resolveMultiSelectValue(newValue, ALL_FILTER_VALUE, this.prevSelectedDocType);
      this.selectedDocType = resolved;
      this.prevSelectedDocType = [...resolved];
    },

    // Handle Supplier multi-select change - IMMEDIATE (frontend filtering)
    handleSupplierChange(newValue: string[]) {
      const resolved = this.resolveMultiSelectValue(newValue, ALL_FILTER_VALUE, this.prevSelectedSupplier);
      this.selectedSupplier = resolved;
      this.prevSelectedSupplier = [...resolved];
    },

    // Handle Assigned Group multi-select change - IMMEDIATE (frontend filtering)
    handleAssignedGroupChange(newValue: string[]) {
      const resolved = this.resolveMultiSelectValue(newValue, ALL_FILTER_VALUE, this.prevSelectedAssignedGroup);
      this.selectedAssignedGroup = resolved;
      this.prevSelectedAssignedGroup = [...resolved];
    },

    flowTypeIcon(value: string): string {
      switch (value) {
        case 'status': return 'swap_horiz';
        case 'modules': return 'settings';
        case 'user': return 'person';
        default: return 'category';
      }
    },

    // Save current filter state for the active tab
    _saveTabFilterState() {
      const state: TabFilterState = {
        selectedSubOrg: [...this.selectedSubOrg],
        prevSelectedSubOrg: [...this.prevSelectedSubOrg],
        selectedDocType: [...this.selectedDocType],
        prevSelectedDocType: [...this.prevSelectedDocType],
        selectedSupplier: [...this.selectedSupplier],
        prevSelectedSupplier: [...this.prevSelectedSupplier],
        selectedAssignedGroup: [...this.selectedAssignedGroup],
        prevSelectedAssignedGroup: [...this.prevSelectedAssignedGroup],
        selectedSteps: [...this.selectedSteps],
        prevSelectedSteps: [...this.prevSelectedSteps],
        documentSearch: this.documentSearch,
        documentSearchInput: this.documentSearchInput,
        chartGroupBy: this.chartGroupBy,
        timeChartGroupBy: this.timeChartGroupBy,
        hiddenDocumentIds: new Set(this.hiddenDocumentIds),
        selectedServices: new Set(this.selectedServices),
        topDocumentsSortOrder: this.topDocumentsSortOrder,
      };
      this._tabFilterStates.set(this.selectedFlowType, state);
    },

    // Restore filter state for a tab, or apply defaults
    _restoreTabFilterState(tab: string) {
      const state = this._tabFilterStates.get(tab);
      if (state) {
        this.selectedSubOrg = [...state.selectedSubOrg];
        this.prevSelectedSubOrg = [...state.prevSelectedSubOrg];
        this.selectedDocType = [...state.selectedDocType];
        this.prevSelectedDocType = [...state.prevSelectedDocType];
        this.selectedSupplier = [...state.selectedSupplier];
        this.prevSelectedSupplier = [...state.prevSelectedSupplier];
        this.selectedAssignedGroup = [...state.selectedAssignedGroup];
        this.prevSelectedAssignedGroup = [...state.prevSelectedAssignedGroup];
        this.selectedSteps = [...state.selectedSteps];
        this.prevSelectedSteps = [...state.prevSelectedSteps];
        this.documentSearch = state.documentSearch;
        this.documentSearchInput = state.documentSearchInput;
        this.chartGroupBy = state.chartGroupBy as any;
        this.timeChartGroupBy = state.timeChartGroupBy as any;
        this.hiddenDocumentIds = new Set(state.hiddenDocumentIds);
        this.selectedServices = new Set(state.selectedServices);
        this.topDocumentsSortOrder = state.topDocumentsSortOrder as any;
      } else {
        // Apply defaults for a tab visited for the first time
        const defaults = createDefaultTabFilterState();
        this.selectedSubOrg = defaults.selectedSubOrg;
        this.prevSelectedSubOrg = defaults.prevSelectedSubOrg;
        this.selectedDocType = defaults.selectedDocType;
        this.prevSelectedDocType = defaults.prevSelectedDocType;
        this.selectedSupplier = defaults.selectedSupplier;
        this.prevSelectedSupplier = defaults.prevSelectedSupplier;
        this.selectedAssignedGroup = defaults.selectedAssignedGroup;
        this.prevSelectedAssignedGroup = defaults.prevSelectedAssignedGroup;
        this.selectedSteps = defaults.selectedSteps;
        this.prevSelectedSteps = defaults.prevSelectedSteps;
        this.documentSearch = defaults.documentSearch;
        this.documentSearchInput = defaults.documentSearchInput;
        this.chartGroupBy = defaults.chartGroupBy as any;
        this.timeChartGroupBy = defaults.timeChartGroupBy as any;
        this.hiddenDocumentIds = new Set(defaults.hiddenDocumentIds);
        this.selectedServices = new Set(defaults.selectedServices);
        this.topDocumentsSortOrder = defaults.topDocumentsSortOrder as any;
      }
    },

    // Handle flow type change - INSTANT (frontend only, no API call needed)
    // Backend returns all flow types, frontend just switches which one to display
    handleFlowTypeChange(newValue: 'modules' | 'user' | 'status') {
      // Switch tab indicator immediately (display only, no heavy recomputation)
      this.displayFlowType = newValue;
      // Show loader, then delay the actual data change so the loader paints first
      this.processing = true;

      // Save current tab's filter state before switching
      this._saveTabFilterState();

      this.$nextTick(() => {
        setTimeout(() => {
          // Restore the target tab's filter state before changing flow type
          // so the watcher knows to skip rebuild
          const hasSavedState = this._tabFilterStates.has(newValue);
          if (hasSavedState) {
            this._skipFlowTypeWatcher = true;
          }
          this._restoreTabFilterState(newValue);
          this.selectedFlowType = newValue;
          this.topDocsCurrentPage = 1;
          this.$nextTick(() => { this.processing = false; });
        }, 50);
      });
    },

    // Jump to a specific page in top documents list
    jumpToTopDocsPage() {
      const page = Math.max(1, Math.min(this.topDocsPageInput || 1, this.topDocsTotalPages));
      this.topDocsCurrentPage = page;
      this.topDocsPageInput = page;
    },

    // Handle Steps multi-select change - IMMEDIATE (frontend only, no API call needed).
    // Drives two effects:
    //   1. Visibility — `visibleFlowElements` hides cards whose base isn't
    //      in `selectedSteps`.
    //   2. Metric recalculation — mirrors the selection into `selectedServices`
    //      so downstream stats (time trend, top docs, table, averages) exclude
    //      the deselected steps, same as the sub-org / doc-type dropdowns.
    // Card clicks remain one-way: they only adjust `selectedServices` (grey-out)
    // and do NOT collapse the dropdown.
    handleStepsChange(newValue: string[]) {
      this.handleMultiSelectChange(newValue, ALL_FILTER_VALUE, 'prevSelectedSteps', 'selectedSteps');

      if (this.selectedSteps.includes(ALL_FILTER_VALUE)) {
        // All steps visible → all visible services selected for metrics.
        const visibleServiceNames = (this.elements as any[]).map(el => el.name);
        this.selectedServices = new Set(visibleServiceNames);
      } else {
        const allowedBases = new Set(this.selectedSteps);
        const next = new Set<string>();
        for (const el of this.elements as any[]) {
          const baseName = el.name.includes('::') ? el.name.split('::')[0] : el.name;
          if (allowedBases.has(baseName)) next.add(el.name);
        }
        this.selectedServices = next;
      }
    },

    // Column visibility drag-and-drop methods

    // Drag from table header to hide column
    onTableDragStart(event: DragEvent) {
      const target = event.target as HTMLElement;
      const th = target.closest('th[data-col-name]') as HTMLElement;
      if (th) {
        const columnName = th.getAttribute('data-col-name');
        if (columnName && columnName !== '__selection__' && columnName !== '__actions__') {
          this.draggedColumnName = columnName;
          this.dragSource = 'table';
        }
      }
    },

    // Drag from hidden column chip to restore column
    onHiddenColumnDragStart(event: DragEvent, columnName: string) {
      this.draggedColumnName = columnName;
      this.dragSource = 'hidden';
      event.dataTransfer?.setData('text/plain', columnName);
    },

    // Common drag end handler
    onDragEnd() {
      this.isDraggingToHide = false;
      this.isDraggingToRestore = false;
      this.draggedColumnName = null;
      this.dragSource = null;
    },

    // Drag over handler (common)
    onColumnDragOver(event: DragEvent) {
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = 'move';
      }
    },

    // Hide zone (left side) - accepts drags from table
    onHideZoneDragEnter(event: DragEvent) {
      event.preventDefault();
      if (this.dragSource === 'table') {
        this.isDraggingToHide = true;
      }
    },

    onHideZoneDragLeave(event: DragEvent) {
      const relatedTarget = event.relatedTarget as HTMLElement;
      const dropZone = event.currentTarget as HTMLElement;
      if (!dropZone.contains(relatedTarget)) {
        this.isDraggingToHide = false;
      }
    },

    onHideZoneDrop(event: DragEvent) {
      event.preventDefault();
      this.isDraggingToHide = false;

      // Only hide if dragged from table
      if (this.dragSource === 'table' && this.draggedColumnName) {
        if (!this.hiddenColumnNames.includes(this.draggedColumnName)) {
          this.hiddenColumnNames.push(this.draggedColumnName);
        }
      }
      this.draggedColumnName = null;
      this.dragSource = null;
    },

    // Table zone (right side) - accepts drags from hidden chips
    onTableDragOver(event: DragEvent) {
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = 'move';
      }
    },

    onTableDragEnter(event: DragEvent) {
      event.preventDefault();
      if (this.dragSource === 'hidden') {
        this.isDraggingToRestore = true;
      }
    },

    onTableDragLeave(event: DragEvent) {
      const relatedTarget = event.relatedTarget as HTMLElement;
      const dropZone = event.currentTarget as HTMLElement;
      if (!dropZone.contains(relatedTarget)) {
        this.isDraggingToRestore = false;
      }
    },

    onTableDrop(event: DragEvent) {
      event.preventDefault();
      this.isDraggingToRestore = false;

      // Only restore if dragged from hidden zone
      if (this.dragSource === 'hidden' && this.draggedColumnName) {
        this.restoreColumn(this.draggedColumnName);
      }
      this.draggedColumnName = null;
      this.dragSource = null;
    },

    restoreColumn(columnName: string) {
      const index = this.hiddenColumnNames.indexOf(columnName);
      if (index > -1) {
        this.hiddenColumnNames.splice(index, 1);
      }
    },

    downloadTableCSV() {
      if (this.tableElements.length === 0) return;

      // Generate filename with current date
      const today = new Date();
      const dateStr = formatDate(today);
      const filename = `analytics_export_${dateStr}.csv`;

      // Use the visible columns for export
      const exportColumns = this.visibleTableColumns;

      try {
        // Export using the CSV utility
        const result = csvExportUtil.methods.createAndExportCSV(
          this.tableElements,
          exportColumns,
          filename
        );

        if (result) {
          notify.success(this.$t('download') + ' CSV');
        } else {
          notify.error(this.$t('error'));
        }
      } catch (error) {
        console.error('CSV export failed:', error);
        notify.error(this.$t('error'));
      }
    },
  },
});
</script>

